// ════════════════════════════════════════════════════════════════════════
// tests/skill-row-upsert.mjs — THE `unknown_skill` INCIDENT, GRADED AGAINST
// REAL POSTGRESQL.
//
//   node tests/skill-row-upsert.mjs            # the guard
//   node tests/skill-row-upsert.mjs --mutate   # plant real defects, prove RED
//
// Ships with: supabase/migrations/2026-08-18-skill-row-upsert.sql
//             (GENERATED by tools/derive-skill-row-upsert.mjs).
//
// ── THE DEFECT CLASS THIS EXISTS FOR ────────────────────────────────────
// hr_apply granted XP with a bare UPDATE and a row-count assertion:
//
//     update public.player_skills set xp = xp + v_n where ...;
//     get diagnostics v_rows = row_count;
//     if v_rows <> 1 then hr_reject('unknown_skill') end if;
//
// which reports TWO unrelated facts with ONE code:
//   (1) the skill id is not in the catalogue        — a real deploy bug
//   (2) this character has no row for a REAL skill  — server bookkeeping
//
// (2) is not an error condition; it is a row to create. Per-skill rows are
// seeded ONCE, at character creation, and the catalogue GROWS afterwards — so
// every character older than a skill lacks that skill's row. When Stonemason
// shipped, pre-Stonemason characters got `unknown_skill` on a legitimate grant;
// the refusal STORED itself against the intent key so "Try again" replayed it;
// and because hr_reject rolls the protected block back WHOLE, each refusal also
// discarded that window's gold, items and every OTHER skill's XP. 51 aggregated
// rejections at severity `incident` in one night, unread until morning.
//
// ⚠ HOW THE FIXTURE REACHES THE INCIDENT'S STATE, AND WHY IT IS A DELETE.
//   `hr_create_character` (as replaced by 2026-08-14-character-bootstrap.sql)
//   correctly seeds a row per skill IN THE CATALOGUE, so a character created
//   TODAY has a stonemason row and cannot reproduce anything. The characters
//   that hit the incident were created BEFORE stonemason entered the catalogue,
//   and nothing re-seeds an existing character — that is the whole defect. A
//   replay cannot rewind the catalogue, so the fixture deletes the row instead,
//   which lands on EXACTLY the state production was in: a live character, a real
//   catalogue skill, no row. SKILL-0 asserts the delete actually removed
//   something, because a fixture step that silently no-ops would make every
//   assertion below pass against the old bare UPDATE.
//
// ⚠ AND THE HAND BACKFILL IS NOT THE FIX. Production was backfilled that night
//   (all user/slot × hr_skills pairs now exist), which removes the symptom and
//   leaves the defect: the NEXT skill added to src/data/skills.js re-creates it
//   for every existing character. This guard therefore grades the GRANT, which
//   is the only place that is correct for a backfilled database and a fresh one.
//
// ── WHAT IT CANNOT PROVE ────────────────────────────────────────────────
// PGlite is ONE backend: the advisory lock hr_apply takes per character is
// exercised and contended by nothing, so "two concurrent grants to the same
// missing skill row" is NOT proven here. It is, however, the one case
// `on conflict` exists for — and the losing session's insert becomes the
// `do update` arm rather than a unique_violation, which is the reason the upsert
// is an upsert and not "select then insert".
// ════════════════════════════════════════════════════════════════════════
import { bootReplay, ROOT } from './schema-replay.mjs';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const problems = [];
const ok = (cond, msg) => { if (!cond) problems.push(msg); };

const UID = '000000cd-0000-4000-a000-0000000000cd';
/* The skill that actually produced the incident. Any catalogue skill would do
   — what matters is that the row is missing — but naming the real one keeps
   the guard readable next to hr_rejections. */
const LATE_SKILL = 'stonemason';
/* A skill whose row is LEFT ALONE, so the "existing row" arm is graded against
   a row that got there the ordinary way. */
const SEEDED_SKILL = 'mining';
const JUNK_SKILL = 'definitely_not_a_skill_zzz';

export async function guard() {
  let db;
  try { ({ db } = await bootReplay()); } catch (e) {
    problems.push(`SKILL-SQL: the migration chain would not apply — ${e.message}`);
    return problems;
  }

  await db.query('insert into auth.users(id) values ($1) on conflict (id) do nothing', [UID]);
  await db.query('insert into profiles(id, display_name) values ($1,$2) '
    + 'on conflict (id) do update set display_name = excluded.display_name', [UID, 'SkillProbe']);
  await db.query("select set_config('request.jwt.claim.sub',$1,false)", [UID]);
  const cr = (await db.query('select hr_create_character(0) r')).rows[0].r;
  if (cr.ok !== true) {
    problems.push(`SKILL-SQL: hr_create_character failed — ${JSON.stringify(cr)}`);
    return problems;
  }

  let version = Number((await db.query(
    'select version::text v from player_state where user_id=$1 and slot=0', [UID])).rows[0].v);
  let n = 0;
  const apply = async (delta) => {
    await db.exec('set role hr_engine');
    let r;
    try {
      r = (await db.query('select hr_apply($1,0,$2,$3,$4::jsonb) r',
        [UID, version, `00000000-0000-4000-c000-${String(++n).padStart(12, '0')}`,
          JSON.stringify(delta)])).rows[0].r;
    } catch (e) { r = { ok: false, error: '__exception', message: e.message }; }
    await db.exec('reset role');
    if (r && r.ok === true) version += 1;
    return r;
  };
  const xpOf = async (skill) => {
    const rows = (await db.query(
      'select xp::text x from player_skills where user_id=$1 and slot=0 and skill_id=$2',
      [UID, skill])).rows;
    return rows.length ? Number(rows[0].x) : null;
  };
  const goldOf = async () => Number((await db.query(
    'select gold::text g from player_state where user_id=$1 and slot=0', [UID])).rows[0].g);

  // ── SKILL-0 — THE FIXTURE PRECONDITION, FIRST AND LOUDLY. ────────────────
  // Everything below is about a MISSING row for a REAL skill. If the row is
  // present, or the skill is not in the catalogue, every assertion passes
  // without the fix.
  const inCatalogue = Number((await db.query(
    'select count(*)::text c from hr_skills where skill_id=$1', [LATE_SKILL])).rows[0].c);
  ok(inCatalogue === 1,
    `SKILL-0: "${LATE_SKILL}" is not in hr_skills — the catalogue moved and this whole guard is `
    + 'grading nothing. Point LATE_SKILL at a skill that IS in the catalogue.');
  ok(await xpOf(SEEDED_SKILL) === 0,
    `SKILL-0: the bootstrap did not seed "${SEEDED_SKILL}" — SKILL-3's control is not a control.`);
  // Rewind this ONE character to the pre-Stonemason state. See the header: the
  // catalogue cannot be rewound, and this is exactly the state production was
  // in — live character, real catalogue skill, no row.
  const del = await db.query(
    'delete from player_skills where user_id=$1 and slot=0 and skill_id=$2', [UID, LATE_SKILL]);
  ok(del.affectedRows === 1,
    `SKILL-0: the fixture delete removed ${del.affectedRows} rows, expected 1 — the character was `
    + `never seeded with "${LATE_SKILL}", so the missing-row case may not be what is being tested.`);
  ok(await xpOf(LATE_SKILL) === null,
    `SKILL-0: "${LATE_SKILL}" still has a row after the fixture delete — SKILL-1 would pass `
    + 'against the old bare UPDATE and prove nothing.');

  // ── CONTROL — an ordinary grant to a SEEDED skill works. ─────────────────
  // Asserted before any refusal, because a probe that cannot make an honest
  // call succeed would report a clean bill for a completely broken hr_apply.
  let r = await apply({ xp: { [SEEDED_SKILL]: 100 } });
  ok(r && r.ok === true, `SKILL-CONTROL: an ordinary XP grant was refused — ${JSON.stringify(r)}`);
  ok(await xpOf(SEEDED_SKILL) === 100,
    `SKILL-CONTROL: ${SEEDED_SKILL} xp is ${await xpOf(SEEDED_SKILL)}, expected 100`);

  // ── SKILL-1 — A KNOWN-BUT-ROWLESS SKILL IS GRANTED, AND THE ROW IS CREATED.
  // This is the incident. Under the bare UPDATE this call answered
  // `unknown_skill` and rolled the whole window back.
  r = await apply({ xp: { [LATE_SKILL]: 250 } });
  ok(r && r.ok === true,
    `SKILL-1: a grant to the REAL catalogue skill "${LATE_SKILL}" was refused — `
    + `${JSON.stringify(r)}. A character with no row for a skill that exists is a row to CREATE, `
    + 'never a refusal; refusing it discards the whole accrual window (the b369 incident).');
  ok(await xpOf(LATE_SKILL) === 250,
    `SKILL-1: after the grant, ${LATE_SKILL} xp is ${await xpOf(LATE_SKILL)}, expected a NEW row `
    + 'at 250. An ok:true that wrote nothing is worse than the refusal it replaced.');

  // ── SKILL-2 — A GENUINELY UNKNOWN SKILL STILL REFUSES, AND MINTS NOTHING.
  // The narrowing must not become a hole: there is NO foreign key from
  // player_skills.skill_id to hr_skills, so an upsert without the catalogue
  // check ahead of it creates a skill row out of a client string.
  const goldBefore = await goldOf();
  r = await apply({ xp: { [JUNK_SKILL]: 10 } });
  ok(r && r.ok === false && r.error === 'unknown_skill',
    `SKILL-2: a grant to "${JUNK_SKILL}" returned ${JSON.stringify(r)} — expected unknown_skill. `
    + 'The catalogue check must run BEFORE the insert, or a client names its own skills.');
  ok(await xpOf(JUNK_SKILL) === null,
    `SKILL-2: a player_skills row was CREATED for "${JUNK_SKILL}" — the upsert ran on an unvalidated `
    + 'client string. That is a skill, and therefore a level, and therefore a leaderboard entry, '
    + 'authored by the client.');
  ok(await goldOf() === goldBefore,
    'SKILL-2: the refusal did not roll the block back whole — gold moved on a rejected delta.');

  // ── SKILL-3 — AN EXISTING ROW IS UNCHANGED IN BEHAVIOUR: ADD, NOT REPLACE.
  // `do update set xp = player_skills.xp + v_n`. Writing `= v_n` would be an
  // XP RESET on every grant to an existing row, i.e. this fix eating the entire
  // game's progression, and it is a one-word slip.
  r = await apply({ xp: { [SEEDED_SKILL]: 40 } });
  ok(r && r.ok === true, `SKILL-3: a second grant was refused — ${JSON.stringify(r)}`);
  ok(await xpOf(SEEDED_SKILL) === 140,
    `SKILL-3: ${SEEDED_SKILL} xp is ${await xpOf(SEEDED_SKILL)}, expected 140 (100 + 40). The `
    + 'conflict arm must ADD to the stored xp, not overwrite it with the delta.');
  // ...and the row this file CREATED accumulates the same way on its second grant.
  r = await apply({ xp: { [LATE_SKILL]: 50 } });
  ok(r && r.ok === true, `SKILL-3: a second grant to ${LATE_SKILL} was refused — ${JSON.stringify(r)}`);
  ok(await xpOf(LATE_SKILL) === 300,
    `SKILL-3: ${LATE_SKILL} xp is ${await xpOf(LATE_SKILL)}, expected 300 — a row created by the `
    + 'upsert must behave exactly like a bootstrap-seeded one from then on.');

  // ── SKILL-4 — MULTI-SKILL DELTA: ONE MISSING ROW NO LONGER POISONS THE REST.
  // The incident's real cost was collateral. hr_reject rolls the protected
  // block back WHOLE, so a stonemason line in a mining window took the mining
  // XP down with it.
  const before = { s: await xpOf(SEEDED_SKILL), l: await xpOf(LATE_SKILL) };
  r = await apply({ xp: { [SEEDED_SKILL]: 7, [LATE_SKILL]: 9, crafting: 11 } });
  ok(r && r.ok === true, `SKILL-4: a mixed grant was refused — ${JSON.stringify(r)}`);
  ok(await xpOf(SEEDED_SKILL) === before.s + 7 && await xpOf(LATE_SKILL) === before.l + 9,
    'SKILL-4: a delta that mixes a seeded skill with a rowless one did not pay both.');

  // ── SKILL-5 — `unknown_skill` IS STILL ON c_release_codes. ────────────────
  // The code is now raised ONLY for a genuinely stale catalogue, which is
  // exactly the "server state that can change underneath an unchanged delta"
  // case that must release its intent key — otherwise the first client to hit
  // it is bricked for up to 25 hours, which is the OTHER half of the incident.
  const src = (await db.query(
    "select prosrc s from pg_proc p join pg_namespace nsp on nsp.oid = p.pronamespace "
    + "where nsp.nspname='public' and p.proname='hr_apply'")).rows[0].s;
  const i = src.indexOf('c_release_codes constant text[] := array[');
  const list = i < 0 ? '' : src.slice(i, src.indexOf('];', i));
  ok(list.includes("'unknown_skill'"),
    'SKILL-5: unknown_skill is no longer on c_release_codes — a stale-catalogue refusal would '
    + 'store itself against the intent key and replay on every retry, which is how 51 rejections '
    + 'became a night-long outage rather than one window.');

  // ── SKILL-7 — THE GRANT IS STILL CLAMPED. ────────────────────────────────
  // A positive control on the clamp that sits three lines above the patched
  // region: a derivation that dropped it would leave an unbounded single grant,
  // and every other assertion here would still be green.
  r = await apply({ xp: { [LATE_SKILL]: 12000001 } });
  ok(r && r.ok === false && r.error === 'xp_clamp',
    `SKILL-7: a 12,000,001 XP grant returned ${JSON.stringify(r)} — expected xp_clamp. The `
    + 'per-call ceiling is the only bound on a single grant.');

  /* ── SKILL-8 — §0's PREDECESSOR ANCHOR MUST DISCRIMINATE (Security S1) ────
     THIS IS THE ONLY ASSERTION HERE THAT DOES NOT NEED A DATABASE, and it
     guards the mistake that has now been made three times on this one chain:
     anchoring a "has my predecessor been applied?" gate on a term the
     predecessor merely MENTIONS rather than on the thing it CHANGED.

     This file's §0 first anchored on `too_many_equip_ops`. Measured over the
     two hr_apply bodies: fight-carry 1, equip-release-codes 2 — because
     fight-carry's equip block is what RAISES the code. The gate would have
     passed against a database that never received equip-release-codes. The
     same class mis-certified equip-release-codes itself as applied to
     production when it had not been.

     So: every term §0 uses must be ABSENT from the predecessor-of-the-
     predecessor and PRESENT in the predecessor. A positive and a negative
     control, which is the only shape of this check that can fail honestly. */
  const readMig = async (f) => (await readFile(
    join(ROOT, 'supabase', 'migrations', f), 'utf8')).replace(/\r\n/g, '\n');
  const applyBody = (sql) => {
    const i = sql.indexOf('create or replace function public.hr_apply(');
    return i < 0 ? '' : sql.slice(i, sql.indexOf('\nend $$;\n', i));
  };
  const ANCHOR = "'bad_equip', 'unknown_equip_slot', 'wrong_slot', 'requirement_not_met',";
  const mine = await readMig('2026-08-18-skill-row-upsert.sql');
  const s0 = mine.slice(0, mine.indexOf('-- ── 1. hr_apply'));
  ok(s0.includes(ANCHOR.replace(/'/g, "''")),
    'SKILL-8: §0 no longer checks the c_release_codes array literal — it is back to a term that '
    + 'fight-carry also contains, so the predecessor gate cannot refuse an unpatched database.');
  const fcBody = applyBody(await readMig('2026-08-17-fight-carry.sql'));
  const erBody = applyBody(await readMig('2026-08-18-equip-release-codes.sql'));
  ok(fcBody.length > 1000 && erBody.length > 1000,
    'SKILL-8: could not extract one of the two hr_apply bodies — the control is not a control.');
  ok(!fcBody.includes(ANCHOR),
    `SKILL-8 (the NEGATIVE control): ${JSON.stringify(ANCHOR)} is present in fight-carry's hr_apply, `
    + 'so it does NOT discriminate and §0 would pass against a database missing '
    + 'equip-release-codes. Pick an anchor that is unique to the predecessor.');
  ok(erBody.includes(ANCHOR),
    `SKILL-8 (the POSITIVE control): ${JSON.stringify(ANCHOR)} is absent from equip-release-codes' `
    + 'hr_apply, so §0 would refuse to install onto the very body this file was derived from.');
  // And the term that FAILED review, named, so nobody reaches for it again.
  ok(fcBody.includes('too_many_equip_ops'),
    'SKILL-8: `too_many_equip_ops` is no longer in fight-carry — the historical note in §0 and the '
    + 'reason this control exists have gone stale; re-measure before trusting either.');

  guard.report = [
    `SKILL: ${LATE_SKILL} row created by the grant and accumulated to ${await xpOf(LATE_SKILL)}; `
    + `${JUNK_SKILL} refused and minted nothing.`,
  ];
  return problems;
}

/* ── MUTANTS ─────────────────────────────────────────────────────────────
   All three edit the GENERATED migration, which is the body that actually
   runs.

   ⚠ EACH MUTANT CARRIES TWO EXTRA EDITS THAT DISABLE THE MIGRATION'S OWN §3,
     AND WITHOUT THEM THIS HARNESS WOULD BE A FRAUD. Measured, not assumed: with
     the plain M3 edit alone, the run went red — with "2026-08-18-skill-row-
     upsert.sql failed to apply: the XP block does not contain …". That is §3(b)
     doing its job, which is good news for the migration and NO news about this
     file: the database never booted, so not one behavioural assertion below
     ever executed, and all three mutants would have reported CAUGHT even if
     SKILL-1..7 asserted nothing at all. That is the always-null-probe family
     wearing a green tick.

     So the static self-check is switched off (§3(a) loses the one term it would
     miss, and §3(b) is short-circuited with a `return;`) and the fault is left
     to reach BEHAVIOUR. §3 is graded separately, by the migration replaying at
     all in every other run of this file.

   tools/derive-skill-row-upsert.mjs --check would also catch these edits — a
   third, different guard, for a different failure (a hand-edited restatement).
   Three independent nets over one change is the point, not redundancy.

   ⚠⚠ DO NOT RUN `--mutate` CONCURRENTLY WITH THE SMOKE SUITE, OR WITH ANOTHER
     MUTATION HARNESS, OR TWICE AT ONCE. It edits a REAL production migration
     in place and restores it afterwards. A suite running beside it reads the
     MUTATED bytes — `tests/run-smoke.mjs` replays the whole chain — so it would
     fail (or, far worse, pass) against a body nobody intended to ship, and the
     two restores can interleave such that `mutation-safety.mjs`'s hash check
     verifies a file the OTHER run is still holding open. That hash check is the
     only thing standing between this harness and the 2026-08-16 incident where
     a sibling left an item-duplication bug in the deployed engine after a
     timeout; do not put it in a position where it can be right about the wrong
     snapshot. Run mutation harnesses one at a time, serially, on an otherwise
     idle tree. */
const MIG = 'supabase/migrations/2026-08-18-skill-row-upsert.sql';
const BLIND = [
  // §3(a)'s term list: swap this file's own change for a term that is present
  // either way, so (a) still runs and still means something.
  ["    'on conflict (user_id, slot, skill_id)']",
    "    'c_max_xp_delta     constant bigint := 12000000']"],
  // §3(b)-(g): short-circuit. `return` in a DO block ends it.
  ['  -- (b) THE XP GRANT IS AN UPSERT AND THE OLD REFUSAL IS GONE',
    '  return; -- MUTATION HARNESS: §3(b)-(g) disabled so the BEHAVIOUR is what fails\n'
    + '  -- (b) THE XP GRANT IS AN UPSERT AND THE OLD REFUSAL IS GONE'],
];
const MUTANTS = [
  {
    id: 'M1', file: MIG,
    what: 'the XP grant reverts to the bare UPDATE + row-count refusal (the incident itself)',
    edits: [[`        insert into public.player_skills (user_id, slot, skill_id, xp)
          values (v_uid, v_slot, k, v_n)
          on conflict (user_id, slot, skill_id)
          do update set xp = player_skills.xp + v_n;`,
    `        update public.player_skills set xp = xp + v_n
          where user_id = v_uid and slot = v_slot and skill_id = k;
        get diagnostics v_rows = row_count;
        if v_rows <> 1 then
          perform public.hr_reject('unknown_skill', jsonb_build_object('skill_id', k));
        end if;`], ...BLIND],
  },
  {
    id: 'M2', file: MIG,
    what: 'the true-unknown check is dropped, so a client string mints its own skill row',
    edits: [['        if not exists (select 1 from public.hr_skills where skill_id = k) then\n'
      + "          perform public.hr_reject('unknown_skill', jsonb_build_object('skill_id', k));\n"
      + '        end if;\n'
      + '        insert into public.player_skills (user_id, slot, skill_id, xp)',
    '        insert into public.player_skills (user_id, slot, skill_id, xp)'], ...BLIND],
  },
  {
    /* ⚠ NO `...BLIND` ON THIS ONE, DELIBERATELY. §3 does not check §0, and
       SKILL-8 is a source read rather than a database assertion — so blinding
       §3 here would prove nothing about the mutant and would only make the
       list look uniform. */
    id: 'M4', file: MIG,
    what: "§0's predecessor gate reverts to a term fight-carry also contains, so it would pass "
      + 'against a database that never received equip-release-codes (Security S1)',
    edits: [["  if position('''bad_equip'', ''unknown_equip_slot'', ''wrong_slot'', "
      + "''requirement_not_met'','\n              in v_src) = 0 then",
    "  if position('too_many_equip_ops' in v_src) = 0 then"]],
  },
  {
    id: 'M3', file: MIG,
    what: 'the conflict arm REPLACES the stored xp instead of adding to it (a total XP reset)',
    edits: [['do update set xp = player_skills.xp + v_n;', 'do update set xp = v_n;'], ...BLIND],
  },
];

async function mutate() {
  const { writeFile } = await import('node:fs/promises');
  const { spawnSync } = await import('node:child_process');
  const { snapshot, assertNoResidue, noteDirtyTree } = await import('./mutation-safety.mjs');
  let bad = 0;
  assertNoResidue(MUTANTS.flatMap((m) => m.edits.map(([from, to]) => (
    { file: join(ROOT, m.file), from, to }))));
  noteDirtyTree([...new Set(MUTANTS.map((m) => m.file))], { cwd: ROOT });
  for (const m of MUTANTS) {
    const path = join(ROOT, m.file);
    const original = snapshot(path);
    /* EVERY anchor must match exactly once, INCLUDING the two that blind §3.
       A blinding edit that silently no-ops puts the run straight back into the
       "§3 failed, so nothing was measured" hole this list exists to escape. */
    let mutated = original;
    let planted = true;
    for (const [from, to] of m.edits) {
      const hits = mutated.split(from).length - 1;
      if (hits !== 1) {
        console.log(`  ! ${m.id}: anchor matched ${hits} times, must match 1 — the mutant is not `
          + `being planted, so its "caught" verdict would be meaningless. Anchor: `
          + `${JSON.stringify(from.slice(0, 60))}`);
        planted = false; break;
      }
      mutated = mutated.replace(from, to);
    }
    if (!planted) { bad++; continue; }
    await writeFile(path, mutated, 'utf8');
    let out;
    try {
      out = spawnSync(process.execPath, [join(ROOT, 'tests', 'skill-row-upsert.mjs')],
        { encoding: 'utf8', timeout: 900000 });
    } finally {
      await writeFile(path, original, 'utf8');
    }
    if (out.status !== 0) {
      const c = (out.stdout || '').split('\n').filter((l) => l.startsWith('  x ')).length;
      console.log(`  ✓ ${m.id} CAUGHT (${c || '?'}) — ${m.what}`);
    } else { console.log(`  ✗ ${m.id} SLIPPED — ${m.what}`); bad++; }
  }
  return bad;
}

if (import.meta.url === pathToFileURL(process.argv[1] || '').href) {
  if (process.argv.includes('--mutate')) {
    console.log('skill-row upsert — mutation harness:');
    const bad = await mutate();
    (await import('./mutation-safety.mjs')).finish(bad ? 1 : 0);
  }
  const found = await guard();
  if (found.length) {
    console.log('skill-row upsert — FAILED:');
    for (const p of found) console.log('  x ' + p);
    process.exit(1);
  }
  console.log('skill-row upsert — a known-but-rowless skill is a row to create, not a refusal.');
  for (const line of guard.report || []) console.log(`  ${line}`);
}
